namespace WunderkindLC.Domain;

// CRM upgrade — Phase 5 (docs/SPEC-crm-upgrade.md §6): dated schedule + floors, task approval,
// per-user home widgets. Columns only — no new tables (migration `CrmWorkspace`, generated by the
// integrator). Existing rows keep today's behaviour with the column defaults.

public partial class Room
{
    /// <summary>Floor the room is on (−2..50). <c>null</c> = «Qavat ko'rsatilmagan». The dated schedule
    /// groups room columns under floor headers (<c>RoomFloors</c>).</summary>
    public int? Floor { get; set; }
}

public partial class WorkTask
{
    /// <summary>Completion must be approved by the creator (or an admin/superadmin). Default for a new task:
    /// on when the assignee is someone other than the creator (<c>WorkTaskApproval.DefaultRequired</c>).
    /// Existing tasks: <c>false</c> — untouched.</summary>
    public bool ApprovalRequired { get; set; }

    /// <summary>When the completion was approved (<c>null</c> = not approved yet). Cleared whenever the task
    /// leaves a done column.</summary>
    public DateTime? ApprovedAt { get; set; }

    /// <summary>Who approved it (AppUser.Id, <c>""</c> = nobody).</summary>
    public string ApprovedById { get; set; } = string.Empty;

    /// <summary>How many times the approver returned the task to work.</summary>
    public int ReturnCount { get; set; }

    /// <summary>Last time it was returned (<c>null</c> = never).</summary>
    public DateTime? LastReturnedAt { get; set; }
}

public partial class UserSettings
{
    /// <summary>Admin home page layout (JSON, <c>HomeLayoutRules</c>): which cards/blocks are shown and in
    /// which order. <c>""</c> = never customised — the client shows the defaults.</summary>
    public string HomeLayout { get; set; } = string.Empty;
}
